/**
 * Rent terms and the rent account for one tenancy.
 *
 * Staff set the rent and cycle here; benefit awards and payer splits live in their own services.
 * Charges per period per payer are generated by the database (refresh_rent_charges) after every
 * write and by the nightly job. Xero stays the ledger of record: nothing here posts to Xero.
 *
 * Rounding (all Postgres round(), half away from zero):
 *   - a part period is pro-rata: round(rent * days / periodDays, 2)
 *   - a percent share is round(rent * pct / 100, 2)
 *   - a fixed share scales with the pro-rata: round(fixed * rent / fullRent, 2)
 *   - the tenant owes rent minus the third-party shares, so the shares of one period always sum to
 *     the rent; a share is capped at what is left; a split counts for a period only if it is in
 *     force on the period's first day.
 * Money crosses this module as integer pence.
 */
import type { ActorDb } from '../../db/context.js';
import type { Pool, PoolClient } from '../../db/pool.js';
import { AppError } from '../../lib/errors.js';
import { convertPence, type RentFrequency } from './money.js';

export type Payer = 'tenant' | 'council_hb' | 'dwp_uc' | 'other_third_party';
const PAYER_ORDER: Payer[] = ['tenant', 'council_hb', 'dwp_uc', 'other_third_party'];

export interface LockedTenancy {
  id: string;
  tid: string;
  startDate: string;
  chargesFrom: string | null;
}

/** Locks the tenancy row (serialises writers and the nightly job). 404 if the TID is unknown. */
export async function lockTenancy(c: PoolClient, tid: string): Promise<LockedTenancy> {
  const { rows } = await c.query<{ id: string; tid: string; start_date: string; charges_from: string | null }>(
    'SELECT id, tid, start_date, charges_from FROM tenancies WHERE tid = $1 FOR UPDATE',
    [tid],
  );
  const r = rows[0];
  if (!r) throw new AppError('not_found', 'No such tenancy');
  return { id: r.id, tid: r.tid, startDate: r.start_date, chargesFrom: r.charges_from };
}

/** Locks the tenancy that owns a row of `table` (by row id). 404 if the row does not exist. */
export async function lockTenancyOf(c: PoolClient, table: 'benefit_awards' | 'payer_splits' | 'payment_methods', rowId: string): Promise<LockedTenancy> {
  const { rows } = await c.query<{ tid: string }>(
    `SELECT t.tid FROM ${table} x JOIN tenancies t ON t.id = x.tenancy_id WHERE x.id = $1`,
    [rowId],
  );
  if (!rows[0]) throw new AppError('not_found', 'Not found');
  return lockTenancy(c, rows[0].tid);
}

/** Lead tenant of the tenancy, or 400. */
export async function leadTenantId(c: PoolClient, tenancyId: string): Promise<string> {
  const { rows } = await c.query<{ tenant_id: string }>(
    'SELECT tenant_id FROM tenancy_tenants WHERE tenancy_id = $1 AND is_lead AND left_on IS NULL',
    [tenancyId],
  );
  if (!rows[0]) throw new AppError('bad_request', 'Tenancy has no lead tenant');
  return rows[0].tenant_id;
}

/** Regenerates stale charges and re-applies receipts; returns the new charge rows created. */
export async function refreshCharges(c: PoolClient, tenancyId: string): Promise<number> {
  const { rows } = await c.query<{ n: number }>('SELECT refresh_rent_charges($1) AS n', [tenancyId]);
  return rows[0]?.n ?? 0;
}

/** 23P01 (exclusion violation) -> 409 'Overlaps an existing <what>'. */
export function overlapError(err: unknown, what: string): unknown {
  if (typeof err === 'object' && err !== null && (err as { code?: unknown }).code === '23P01') {
    return new AppError('conflict', `Overlaps an existing ${what}`);
  }
  return err;
}

export interface SetRentInput {
  amountPence: number;
  frequency: RentFrequency;
  effectiveFrom: string;
}

/** Sets the rent from a date; returns the tenancy's TID. */
export async function setRent(db: ActorDb, tid: string, input: SetRentInput): Promise<string> {
  try {
    return await db.tx(async (c) => {
      const t = await lockTenancy(c, tid);
      const { amountPence, frequency, effectiveFrom: from } = input;
      if (from < t.startDate) throw new AppError('bad_request', 'Before the tenancy started');

      const open = (
        await c.query<{ id: string; effective_from: string; frequency: RentFrequency }>(
          'SELECT id, effective_from, frequency FROM rent_schedules WHERE tenancy_id = $1 AND effective_to IS NULL',
          [t.id],
        )
      ).rows[0];

      if (open && from < open.effective_from) throw new AppError('bad_request', 'Before the current rent');
      if (open && from === open.effective_from) {
        await c.query(
          `UPDATE rent_schedules SET amount = ($2::int)::numeric / 100, frequency = $3, reason = 'staff' WHERE id = $1`,
          [open.id, amountPence, frequency],
        );
      } else {
        if (open) await c.query('UPDATE rent_schedules SET effective_to = $2::date - 1 WHERE id = $1', [open.id, from]);
        await c.query(
          `INSERT INTO rent_schedules (tenancy_id, amount, frequency, effective_from, reason)
           VALUES ($1, ($2::int)::numeric / 100, $3, $4, 'staff')`,
          [t.id, amountPence, frequency, from],
        );
      }

      if (open && open.frequency !== frequency) await reconvertAwardSplits(c, t.id, from, frequency);
      if (t.chargesFrom === null) await c.query('UPDATE tenancies SET charges_from = $2 WHERE id = $1', [t.id, from]);
      await refreshCharges(c, t.id);
      return t.tid;
    });
  } catch (err) {
    throw overlapError(err, 'rent schedule');
  }
}

/** The rent cycle changed: award-linked splits are restated per new cycle from `from`. */
async function reconvertAwardSplits(c: PoolClient, tenancyId: string, from: string, freq: RentFrequency): Promise<void> {
  const { rows } = await c.query<{
    id: string;
    payer: Payer;
    benefit_award_id: string;
    effective_from: string;
    effective_to: string | null;
    award_pence: number;
    award_frequency: RentFrequency;
  }>(
    `SELECT ps.id, ps.payer, ps.benefit_award_id, ps.effective_from, ps.effective_to,
            (ba.award_amount * 100)::int AS award_pence, ba.award_frequency
       FROM payer_splits ps JOIN benefit_awards ba ON ba.id = ps.benefit_award_id
      WHERE ps.tenancy_id = $1 AND (ps.effective_to IS NULL OR ps.effective_to >= $2::date)
      ORDER BY ps.effective_from`,
    [tenancyId, from],
  );
  for (const s of rows) {
    const pence = convertPence(s.award_pence, s.award_frequency, freq);
    if (s.effective_from >= from) {
      await c.query('UPDATE payer_splits SET fixed_amount = ($2::int)::numeric / 100 WHERE id = $1', [s.id, pence]);
    } else {
      await c.query('UPDATE payer_splits SET effective_to = $2::date - 1 WHERE id = $1', [s.id, from]);
      await c.query(
        `INSERT INTO payer_splits (tenancy_id, payer, benefit_award_id, fixed_amount, effective_from, effective_to)
         VALUES ($1, $2, $3, ($4::int)::numeric / 100, $5, $6)`,
        [tenancyId, s.payer, s.benefit_award_id, pence, from, s.effective_to],
      );
    }
  }
}

// ---------------------------------------------------------------------------------------------
// Read model
// ---------------------------------------------------------------------------------------------
export interface RentAccount {
  tenancy: { id: string; tid: string; startDate: string; endDate: string | null; status: string; chargesFrom: string | null };
  schedules: { id: string; amountPence: number; frequency: RentFrequency; effectiveFrom: string; effectiveTo: string | null; reason: string | null }[];
  awards: {
    id: string;
    benefit: 'UC' | 'HB' | 'DHP';
    payingBody: string;
    claimReference: string | null;
    awardPence: number;
    awardFrequency: RentFrequency;
    paidTo: 'landlord_direct' | 'tenant';
    effectiveFrom: string;
    effectiveTo: string | null;
  }[];
  splits: {
    id: string;
    payer: Payer;
    benefitAwardId: string | null;
    sharePercent: string | null;
    fixedPence: number | null;
    effectiveFrom: string;
    effectiveTo: string | null;
  }[];
  paymentMethods: {
    id: string;
    payer: Payer;
    method: string;
    expectedPence: number | null;
    expectedFrequency: RentFrequency | null;
    expectedDay: number | null;
    referenceHint: string | null;
    effectiveFrom: string;
    effectiveTo: string | null;
  }[];
  periods: { periodStart: string; periodEnd: string; dueDate: string; byPayer: Partial<Record<Payer, number>>; totalPence: number }[];
  payers: {
    payer: Payer;
    chargedPence: number;
    receivedPence: number;
    adjustmentsPence: number;
    balancePence: number;
    lines: { date: string; kind: 'charge' | 'adjustment' | 'receipt'; description: string; amountPence: number; balancePence: number }[];
  }[];
}

const KIND_ORDER = { charge: 0, adjustment: 1, receipt: 2 } as const;

export async function getRentAccount(pool: Pool, tid: string): Promise<RentAccount> {
  const t = (
    await pool.query<{ id: string; tid: string; start_date: string; end_date: string | null; status: string; charges_from: string | null }>(
      'SELECT id, tid, start_date, end_date, status::text AS status, charges_from FROM tenancies WHERE tid = $1',
      [tid],
    )
  ).rows[0];
  if (!t) throw new AppError('not_found', 'No such tenancy');
  const id = t.id;

  const [schedules, awards, splits, methods, charges, receipts, adjustments] = await Promise.all([
    pool.query(
      `SELECT id, (amount*100)::int AS pence, frequency::text AS frequency, effective_from, effective_to, reason
         FROM rent_schedules WHERE tenancy_id = $1 ORDER BY effective_from DESC`,
      [id],
    ),
    pool.query(
      `SELECT id, benefit::text AS benefit, paying_body, claim_reference, (award_amount*100)::int AS pence,
              award_frequency::text AS freq, paid_to::text AS paid_to, effective_from, effective_to
         FROM benefit_awards WHERE tenancy_id = $1 ORDER BY effective_from DESC, created_at DESC`,
      [id],
    ),
    pool.query(
      `SELECT id, payer::text AS payer, benefit_award_id, share_percent::text AS share_percent,
              (fixed_amount*100)::int AS pence, effective_from, effective_to
         FROM payer_splits WHERE tenancy_id = $1 ORDER BY effective_from DESC, payer`,
      [id],
    ),
    pool.query(
      `SELECT id, payer::text AS payer, method::text AS method, (expected_amount*100)::int AS pence,
              expected_frequency::text AS freq, expected_day, reference_hint, effective_from, effective_to
         FROM payment_methods WHERE tenancy_id = $1 ORDER BY effective_from DESC, created_at DESC`,
      [id],
    ),
    pool.query<{ payer: Payer; period_start: string; period_end: string; due_date: string; pence: number }>(
      `SELECT payer::text AS payer, period_start, period_end, due_date, (amount*100)::int AS pence
         FROM rent_charges WHERE tenancy_id = $1 AND due_date <= current_date ORDER BY due_date, period_start`,
      [id],
    ),
    pool.query<{ payer: Payer; received_on: string; pence: number }>(
      `SELECT payer::text AS payer, received_on, (amount*100)::int AS pence
         FROM receipts WHERE tenancy_id = $1 AND status = 'active' ORDER BY received_on, created_at`,
      [id],
    ),
    pool.query<{ payer: Payer; effective_on: string; kind: string; reason: string; pence: number }>(
      `SELECT payer::text AS payer, effective_on, kind::text AS kind, reason, (amount*100)::int AS pence
         FROM adjustments WHERE tenancy_id = $1 ORDER BY effective_on, created_at`,
      [id],
    ),
  ]);

  // Per period, newest first.
  const byStart = new Map<string, RentAccount['periods'][number]>();
  for (const ch of charges.rows) {
    let p = byStart.get(ch.period_start);
    if (!p) {
      p = { periodStart: ch.period_start, periodEnd: ch.period_end, dueDate: ch.due_date, byPayer: {}, totalPence: 0 };
      byStart.set(ch.period_start, p);
    }
    p.byPayer[ch.payer] = (p.byPayer[ch.payer] ?? 0) + ch.pence;
    p.totalPence += ch.pence;
  }
  const periods = [...byStart.values()].sort((a, b) => (a.dueDate < b.dueDate ? 1 : a.dueDate > b.dueDate ? -1 : 0));

  // Per payer: charges, adjustments and receipts in date order with a running balance.
  interface Raw {
    date: string;
    kind: 'charge' | 'adjustment' | 'receipt';
    description: string;
    signed: number;
  }
  const raw = new Map<Payer, Raw[]>();
  const push = (payer: Payer, r: Raw) => {
    const list = raw.get(payer) ?? [];
    list.push(r);
    raw.set(payer, list);
  };
  for (const ch of charges.rows) {
    push(ch.payer, { date: ch.due_date, kind: 'charge', description: `Rent ${ch.period_start} to ${ch.period_end}`, signed: ch.pence });
  }
  for (const a of adjustments.rows) {
    push(a.payer, { date: a.effective_on, kind: 'adjustment', description: `${a.kind.replace(/_/g, ' ')}: ${a.reason}`, signed: a.pence });
  }
  for (const r of receipts.rows) {
    push(r.payer, { date: r.received_on, kind: 'receipt', description: 'Payment received', signed: -r.pence });
  }

  const payers: RentAccount['payers'] = PAYER_ORDER.filter((p) => raw.has(p)).map((payer) => {
    const sorted = raw
      .get(payer)!
      .sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : KIND_ORDER[a.kind] - KIND_ORDER[b.kind]));
    let balance = 0;
    let charged = 0;
    let received = 0;
    let adj = 0;
    const lines = sorted.map((l) => {
      balance += l.signed;
      if (l.kind === 'charge') charged += l.signed;
      else if (l.kind === 'receipt') received -= l.signed;
      else adj += l.signed;
      return { date: l.date, kind: l.kind, description: l.description, amountPence: l.signed, balancePence: balance };
    });
    return { payer, chargedPence: charged, receivedPence: received, adjustmentsPence: adj, balancePence: balance, lines };
  });

  const n = (v: unknown): number | null => (v === null || v === undefined ? null : Number(v));
  return {
    tenancy: { id: t.id, tid: t.tid, startDate: t.start_date, endDate: t.end_date, status: t.status, chargesFrom: t.charges_from },
    schedules: schedules.rows.map((r) => ({
      id: r.id,
      amountPence: r.pence,
      frequency: r.frequency,
      effectiveFrom: r.effective_from,
      effectiveTo: r.effective_to,
      reason: r.reason,
    })),
    awards: awards.rows.map((r) => ({
      id: r.id,
      benefit: r.benefit,
      payingBody: r.paying_body,
      claimReference: r.claim_reference,
      awardPence: r.pence,
      awardFrequency: r.freq,
      paidTo: r.paid_to,
      effectiveFrom: r.effective_from,
      effectiveTo: r.effective_to,
    })),
    splits: splits.rows.map((r) => ({
      id: r.id,
      payer: r.payer,
      benefitAwardId: r.benefit_award_id,
      sharePercent: r.share_percent,
      fixedPence: n(r.pence),
      effectiveFrom: r.effective_from,
      effectiveTo: r.effective_to,
    })),
    paymentMethods: methods.rows.map((r) => ({
      id: r.id,
      payer: r.payer,
      method: r.method,
      expectedPence: n(r.pence),
      expectedFrequency: r.freq,
      expectedDay: n(r.expected_day),
      referenceHint: r.reference_hint,
      effectiveFrom: r.effective_from,
      effectiveTo: r.effective_to,
    })),
    periods,
    payers,
  };
}
